"""Generate a VapourSynth script that wraps vsmlrt — it does not vendor RIFE or ESRGAN."""

from __future__ import annotations

import json
from pathlib import Path

from params import PipelineParams
from rife_plan import RifePlan, rife_plan


HEADER = '''\
# Generated by Anime Player v1. Do not edit by hand.
# Wraps vsmlrt TensorRT RIFE (FP16) at SOURCE resolution, then Real-ESRGAN anime,
# then fits to 2560x1440. No live/realtime interpolation.
'''


def render_vpy(
    source: Path,
    params: PipelineParams,
    plan: RifePlan | None = None,
    trt_cache: Path | None = None,
) -> str:
    params.validate()
    src = json.dumps(str(source))
    model = json.dumps(params.rife_model)
    esrgan = json.dumps(params.esrgan_model)
    cache = json.dumps(str(trt_cache) if trt_cache else "")
    plan_json = json.dumps(
        {
            "kind": (plan.kind if plan else None),
            "multi": (plan.multi if plan else None),
            "cycle": (plan.cycle if plan else None),
        }
    )
    return f'''{HEADER}
import os
import sys
import vapoursynth as vs

core = vs.core
SOURCE = {src}
RIFE_MODEL_NAME = {model}
ESRGAN_MODEL_NAME = {esrgan}
TARGET_W = {params.target_width}
TARGET_H = {params.target_height}
TARGET_FPS = {params.target_fps}
FP16 = {str(params.rife_fp16)}
WORKSPACE_MB = {params.trt_workspace_mb}
TRT_CACHE = {cache}
PLAN = {plan_json}
PRESERVE_ASPECT = {str(params.preserve_aspect)}

# --- load ---
def _load(path: str) -> vs.VideoNode:
    if hasattr(core, "bs"):
        return core.bs.VideoSource(path)
    if hasattr(core, "lsmas"):
        return core.lsmas.LWLibavSource(path)
    if hasattr(core, "ffms2"):
        return core.ffms2.Source(path)
    raise RuntimeError("Need BestSource, L-SMASH, or FFMS2 in this VapourSynth install")

clip = _load(SOURCE)
src_fps = float(clip.fps_num) / float(clip.fps_den) if clip.fps_den else 0.0

# RIFE and Real-ESRGAN run at SOURCE resolution. Do not resize before RIFE.
def _to_rgbh(c: vs.VideoNode) -> vs.VideoNode:
    if c.format.color_family == vs.RGB and c.format.bits_per_sample == 16 and c.format.sample_type == vs.FLOAT:
        return c
    matrix = "709"
    return core.resize.Bicubic(c, format=vs.RGBH, matrix_in_s=matrix)

try:
    from vsmlrt import Backend, RIFE, RIFEModel, RealESRGAN, RealESRGANModel
except ImportError as exc:
    raise RuntimeError(
        "vsmlrt is not importable. Install vs-mlrt into portable/vapoursynth "
        "(wrap it; do not fork) and add CUDA/TensorRT DLLs to portable/cuda and portable/tensorrt."
    ) from exc

def _rife_enum(name: str):
    key = "v" + name.lstrip("v").replace(".", "_")
    if hasattr(RIFEModel, key):
        return getattr(RIFEModel, key)
    if hasattr(RIFEModel, name):
        return getattr(RIFEModel, name)
    # v4.6 is the locked default
    return getattr(RIFEModel, "v4_6")

def _esrgan_enum(name: str):
    if hasattr(RealESRGANModel, name):
        return getattr(RealESRGANModel, name)
    if hasattr(RealESRGANModel, "animevideov3"):
        return RealESRGANModel.animevideov3
    return name

backend_kw = dict(fp16=FP16, device_id=0, workspace=WORKSPACE_MB * 1024 * 1024, num_streams=1)
if TRT_CACHE:
    os.makedirs(TRT_CACHE, exist_ok=True)
    backend_kw["output_filename"] = None  # vsmlrt hashes engines; cache dir is via env VSMLRT_CACHE_PATH
try:
    backend = Backend.TRT(**backend_kw)
except TypeError:
    backend_kw.pop("workspace", None)
    backend = Backend.TRT(fp16=FP16, device_id=0)

clip = _to_rgbh(clip)

# --- RIFE at source resolution ---
plan = PLAN if PLAN.get("kind") else None
if plan is None:
    # computed at generation time; fallback if the worker omitted it
    if src_fps <= 0:
        kind, multi, cycle = "skip", None, None
    elif src_fps >= TARGET_FPS - 0.5:
        kind, multi, cycle = "skip", None, None
    elif abs(src_fps - 24.0) < 0.08 or abs(src_fps - 23.976) < 0.08:
        kind, multi, cycle = "multiply_then_thin", 5, 2
    elif abs(src_fps - 30.0) < 0.08 or abs(src_fps - 29.97) < 0.08:
        kind, multi, cycle = "multiply", 2, None
    else:
        kind, multi, cycle = "multiply", max(2, int(round(TARGET_FPS / src_fps))), None
else:
    kind, multi, cycle = plan.get("kind"), plan.get("multi"), plan.get("cycle")

if kind != "skip" and multi:
    clip = RIFE(clip, model=_rife_enum(RIFE_MODEL_NAME), backend=backend, multi=int(multi))
    if kind == "multiply_then_thin" and cycle and int(cycle) > 1:
        clip = core.std.SelectEvery(clip, cycle=int(cycle), offsets=[0])

# --- Real-ESRGAN anime, then fit 2560x1440 ---
need_up = clip.width < TARGET_W or clip.height < TARGET_H
if need_up:
    scale = 2
    if clip.width * 2 < TARGET_W and clip.height * 2 < TARGET_H:
        scale = 4
    clip = RealESRGAN(
        clip,
        model=_esrgan_enum(ESRGAN_MODEL_NAME),
        backend=backend,
        scale=scale,
    )

def _fit(c: vs.VideoNode, w: int, h: int) -> vs.VideoNode:
    if c.width == w and c.height == h:
        return c
    if not PRESERVE_ASPECT:
        return core.resize.Spline36(c, w, h)
    scale = min(w / c.width, h / c.height)
    nw = max(2, int(round(c.width * scale / 2.0) * 2))
    nh = max(2, int(round(c.height * scale / 2.0) * 2))
    if nw != c.width or nh != c.height:
        c = core.resize.Spline36(c, nw, nh)
    if nw != w or nh != h:
        c = core.std.AddBorders(
            c,
            left=(w - nw) // 2,
            right=w - nw - (w - nw) // 2,
            top=(h - nh) // 2,
            bottom=h - nh - (h - nh) // 2,
        )
    return c

clip = _fit(clip, TARGET_W, TARGET_H)
clip = core.resize.Spline36(clip, format=vs.YUV420P10, matrix_s="709")
clip.set_output()
'''


def write_vpy(path: Path, source: Path, params: PipelineParams, src_fps: float, trt_cache: Path | None) -> Path:
    plan = rife_plan(src_fps, params.target_fps)
    path.write_text(render_vpy(source, params, plan, trt_cache), encoding="utf-8")
    return path
